420	function isLocalAsset(url: string | null): url is string {
421	  return !!url && url.startsWith("/") && !url.startsWith("//");
422	}
423	
424	export type PreviewAssembly = {
425	  /** The complete self-contained document for the iframe's `srcdoc`. */
426	  doc: string;
427	  /** Build paths referenced by index.html that we could not inline. */
428	  missing: string[];
429	};
430	
431	/**
432	 * Turns the built index.html plus a map of build files into one self-contained
433	 * document with the selection agent injected.
434	 *
435	 * `fetchAsset` is given a build-relative path ("assets/index-abc.js") and
436	 * returns its text, or null if it could not be read. Parsing goes through
437	 * DOMParser rather than regex: it neither executes scripts nor loads
438	 * subresources, and it cannot be fooled by markup inside an attribute.
439	 */
440	export async function buildPreviewDocument(
441	  indexHtml: string,
442	  fetchAsset: (path: string) => Promise<string | null>,
443	): Promise<PreviewAssembly> {
444	  const missing: string[] = [];
445	  const doc = new DOMParser().parseFromString(indexHtml, "text/html");
446	  // DOMParser always synthesises <head> and <body> for text/html; the fallback
447	  // is only here so a hand-written fragment can never drop the policy.
448	  const head: Element = doc.head ?? doc.documentElement;
449	
450	  // Vite emits these to warm the module graph. Every one of them would be a
451	  // blocked request in the assembled document, so they are noise at best.
452	  doc.querySelectorAll('link[rel="modulepreload"], link[rel="preload"]').forEach((el) => {
453	    if (isLocalAsset(el.getAttribute("href"))) el.remove();
454	  });
455	
456	  // Stylesheets -> <style>. `crossorigin` goes with the href.
457	  for (const link of Array.from(doc.querySelectorAll('link[rel="stylesheet"]'))) {
458	    const href = link.getAttribute("href");
459	    if (!isLocalAsset(href)) continue;
460	    const css = await fetchAsset(href.replace(/^\//, ""));
461	    if (css === null) {
462	      missing.push(href);
463	      continue;
464	    }
465	    const style = doc.createElement("style");
466	    // Escaped BEFORE it goes in: the HTML serializer emits <style>/<script>
467	    // text raw, so escaping afterwards would already be too late.
468	    style.textContent = inlineStyle(css);
469	    link.replaceWith(style);
470	  }
471	
472	  // Scripts -> inline. A module script is ALWAYS a CORS-mode fetch, so this is
473	  // not an optimisation: it is the only way the bundle can run in an opaque
474	  // origin without the asset route serving Access-Control-Allow-Origin.
475	  for (const script of Array.from(doc.querySelectorAll("script[src]"))) {
476	    const src = script.getAttribute("src");
477	    if (!isLocalAsset(src)) continue;
478	    const js = await fetchAsset(src.replace(/^\//, ""));
479	    if (js === null) {
480	      missing.push(src);
481	      continue;
482	    }
483	    const inline = doc.createElement("script");
484	    const type = script.getAttribute("type");
485	    if (type) inline.setAttribute("type", type);
486	    inline.textContent = inlineScript(js);
487	    script.replaceWith(inline);
488	  }
489	
490	  // First child of <head>: a meta policy only governs what is parsed after it.
491	  const meta = doc.createElement("meta");
492	  meta.setAttribute("http-equiv", "Content-Security-Policy");
493	  meta.setAttribute("content", PREVIEW_META_CSP);
494	  head.insertBefore(meta, head.firstChild);
495	
496	  // Last child of <body>: the agent wants the finished DOM to walk.
497	  const agent = doc.createElement("script");
498	  agent.setAttribute("data-kodely-ui", "1");
499	  agent.textContent = inlineScript(AGENT_SOURCE);
500	  (doc.body ?? doc.documentElement).appendChild(agent);
501	
502	  // outerHTML drops the doctype; without it the frame renders in quirks mode
503	  // and every generated layout shifts.
504	  return { doc: `<!doctype html>${doc.documentElement.outerHTML}`, missing };
505	}
