  .replace(/type LinkProps[\s\S]*$/, "");

const dir = mkdtempSync(join(tmpdir(), "kodely-router-"));
writeFileSync(join(dir, "router.ts"), src, "utf8");
writeFileSync(
  join(dir, "pages.ts"),
  `export type PageDef = { path: string; label: string; component: unknown; nav?: boolean };
const C = (n: string) => n;
export const PAGES: PageDef[] = [
  { path: "/", label: "Home", component: C("Home") },
  { path: "/about", label: "About", component: C("About") },
  { path: "/services/fitting", label: "Fitting", component: C("Fitting") },
  { path: "/legal/terms", label: "Terms", component: C("Terms"), nav: false },
];
`,
  "utf8",
);

// Reload the module for each scenario, since mountPrefix caches.
let scenario = 0;
async function load(pathname, dataPage) {
  globalThis.document = { getElementById: () => ({ dataset: { page: dataPage } }) };
  globalThis.location = pathname === null ? undefined : { pathname };
  return import(pathToFileURL(join(dir, "router.ts")).href + `?v=${scenario++}`);
}

// ── page resolution: from the document, never from the URL ────────────────
{
  const r = await load("/about", "/about");
  assert.equal(r.resolvePage("/about").label, "About");
  assert.equal(r.resolvePage("/").label, "Home");
  assert.equal(r.resolvePage("/services/fitting").label, "Fitting");
  assert.equal(r.resolvePage("about").label, "About", "unslashed");
  assert.equal(r.resolvePage("/About/").label, "About", "trailing slash + case");
  assert.equal(r.resolvePage("/nope").label, "Home", "unknown falls back to home");
  assert.deepEqual(r.navPages().map((p) => p.label), ["Home", "About", "Fitting"]);
  console.log("resolvePage / navPages: ok");
}

// ── hrefs at every mount the site is served from ──────────────────────────
const cases = [
  // [pathname, data-page, expected href("/about"), expected href("/")]
  ["/", "/", "/about", "/"],
  ["/index.html", "/", "/about", "/"],
  ["/about", "/about", "/about", "/"],
  ["/about.html", "/about", "/about", "/"],
  ["/services/fitting", "/services/fitting", "/about", "/"],
  // staging path form
  ["/api/site/meridian", "/", "/api/site/meridian/about", "/api/site/meridian/"],
  ["/api/site/meridian/", "/", "/api/site/meridian/about", "/api/site/meridian/"],
  ["/api/site/meridian/index.html", "/", "/api/site/meridian/about", "/api/site/meridian/"],
  ["/api/site/meridian/about", "/about", "/api/site/meridian/about", "/api/site/meridian/"],
  ["/api/site/meridian/about.html", "/about", "/api/site/meridian/about", "/api/site/meridian/"],
  [
    "/api/site/meridian/services/fitting",
    "/services/fitting",
    "/api/site/meridian/about",
    "/api/site/meridian/",
  ],
  // editor preview: about:srcdoc has no absolute pathname
  ["srcdoc", "/", "/about", "/"],
];

for (const [pathname, dataPage, wantAbout, wantHome] of cases) {
  const r = await load(pathname, dataPage);
  const gotAbout = r.href("/about");
  const gotHome = r.href("/");
  const ok = gotAbout === wantAbout && gotHome === wantHome;
  console.log(
    `${ok ? "ok  " : "FAIL"} ${pathname.padEnd(38)} data-page=${dataPage.padEnd(18)} -> ${gotAbout}  |  ${gotHome}`,
  );
  assert.equal(gotAbout, wantAbout, pathname);
  assert.equal(gotHome, wantHome, pathname);
  assert.equal(r.currentPath(), dataPage);
}

// A slug that collides with a page name must not confuse the prefix.
{
  const r = await load("/api/site/about", "/");
  assert.equal(r.href("/about"), "/api/site/about/about", "slug named 'about'");
  console.log("ok   slug/page-name collision handled");
}

