// Serves the built multi-page dist at a HOST ROOT, the way <slug>.kodely.site
// does, with the same extensionless resolution the site route now performs.
// Only so a real browser can run the bundle: the Next path form
// (/api/site/<slug>/…) cannot, because vite emits absolute /assets/ URLs —
// a pre-existing staging limitation, unrelated to multi-page.
import { createServer } from "node:http";
import { readFileSync } from "node:fs";

const { FOUNDATION_FILES } = await import("file:///C:/Users/edmem/kodely-prod/lib/foundation.ts");
const { buildSite } = await import("file:///C:/Users/edmem/kodely-prod/lib/build-site.ts");

for (const line of readFileSync("C:/Users/edmem/kodely-prod/.env", "utf8").split(/\r?\n/)) {
  const m = line.match(/^(KODELY_FOUNDATION_DIR)=(.*)$/);
  if (m) process.env[m[1]] ??= m[2].trim();
}

const shell = (pagePath, title) => `<!doctype html>
<html lang="en"><head><meta charset="UTF-8" /><title>${title}</title></head>
<body><div id="root" data-page="${pagePath}"></div>
<script type="module" src="/src/main.tsx"></script></body></html>
`;

const out = await buildSite({
  ...FOUNDATION_FILES,
  "index.html": shell("/", "Meridian Joinery"),
  "about.html": shell("/about", "About — Meridian Joinery"),
  "services/fitting.html": shell("/services/fitting", "Kitchen fitting — Meridian"),
  "src/pages.tsx": `import type { PageDef } from "./router";
import Home from "./pages/Home";
import About from "./pages/About";
import Fitting from "./pages/Fitting";
export const PAGES: PageDef[] = [
  { path: "/", label: "Home", component: Home },
  { path: "/about", label: "About", component: About },
  { path: "/services/fitting", label: "Fitting", component: Fitting },
];
`,
  "src/pages/About.tsx": `import { Section } from "../components/ui/Section";
import { Link } from "../router";
export default function About() {
  return (
    <Section>
      <h1 id="page-heading" className="text-4xl font-bold">About Meridian</h1>
      <p className="mt-4">A two-person workshop in Bedminster.</p>
      <Link to="/services/fitting" className="underline">How fitting works</Link>
    </Section>
  );
}
`,
  "src/pages/Fitting.tsx": `import { Section } from "../components/ui/Section";
export default function Fitting() {
  return <Section><h1 id="page-heading" className="text-4xl font-bold">Kitchen fitting</h1></Section>;
